/** 기준일 이전(포함)의 거래만 보여줄 때 사용합니다. 날짜는 YYYY-MM-DD 형식입니다. */
export function getMockTransactionMonthsUpTo(asOfDate: string): TransactionMonth[] {
  return mockTransactionMonths
    .map((month) => ({
      ...month,
      days: month.days.filter((day) => day.date <= asOfDate),
    }))
    .filter((month) => month.days.length > 0);
}
